package fizeau

import (
	"path/filepath"
	"sync"
	"sync/atomic"
	"time"

	agentcore "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	"github.com/DocumentDrivenDX/fizeau/internal/session"
)

// serviceSessionLog is the service-owned writer that persists the session
// lifecycle records (session.start + session.end) for one Execute call. It
// is constructed in runExecute after the route is resolved and torn down in
// a defer on the same goroutine. Sub-paths (runNative, runSubprocess, ...)
// emit the terminal event through finalizeAndEmit, which delegates here to
// keep the session log in sync with the public event stream.
type serviceSessionLog struct {
	logger    *session.Logger
	path      string
	sessionID string
	decision  RouteDecision
	override  *overrideContext
	endOnce   sync.Once
	endWrote  atomic.Bool
	closeOnce sync.Once

	progressMu     sync.Mutex
	lastProgressAt time.Time
}

// openSessionLog creates the session-log writer for req and emits the
// session.start record. A nil-or-empty req.SessionLogDir yields a no-op
// writer so callers don't need to branch on whether logging is enabled.
func (s *service) openSessionLog(req ServiceExecuteRequest, decision RouteDecision, sessionID string) *serviceSessionLog {
	if req.SessionLogDir == "" || sessionID == "" {
		return &serviceSessionLog{}
	}
	logger := session.NewLogger(req.SessionLogDir, sessionID)
	sl := &serviceSessionLog{
		logger:    logger,
		path:      filepath.Join(req.SessionLogDir, sessionID+".jsonl"),
		sessionID: sessionID,
		decision:  decision,
	}
	// CONTRACT-003: echo top-level Role + CorrelationID into the
	// session-log header (one line per session). Top-level wins over
	// any caller Metadata entry under the reserved keys.
	headerMeta := metaWithRoleAndCorrelation(req.Metadata, req.Role, req.CorrelationID)
	start := session.SessionStartData{
		Provider:               s.providerTypeLabel(decision.Provider),
		Model:                  decision.Model,
		SelectedProvider:       decision.Provider,
		SelectedEndpoint:       decision.Endpoint,
		SelectedServerInstance: decision.ServerInstance,
		SelectedRoute:          req.SelectedRoute,
		Sticky: session.RoutingStickyState{
			KeyPresent:     req.CorrelationID != "",
			Assignment:     decision.Sticky.Assignment,
			ServerInstance: decision.Sticky.ServerInstance,
			Reason:         decision.Sticky.Reason,
		},
		Utilization: session.RoutingUtilizationState{
			Source:         decision.Utilization.Source,
			Freshness:      decision.Utilization.Freshness,
			ActiveRequests: decision.Utilization.ActiveRequests,
			QueuedRequests: decision.Utilization.QueuedRequests,
			MaxConcurrency: decision.Utilization.MaxConcurrency,
			CachePressure:  decision.Utilization.CachePressure,
			ObservedAt:     decision.Utilization.ObservedAt,
		},
		RequestedHarness:  req.Harness,
		ResolvedHarness:   decision.Harness,
		HarnessSource:     harnessSource(req),
		RequestedModel:    req.Model,
		RequestedModelRef: req.ModelRef,
		ResolvedModelRef:  req.ResolvedModelRef,
		ResolvedModel:     decision.Model,
		Reasoning:         req.Reasoning,
		WorkDir:           req.WorkDir,
		MaxIterations:     req.MaxIterations,
		Prompt:            req.Prompt,
		SystemPrompt:      req.SystemPrompt,
		Metadata:          headerMeta,
	}
	logger.Emit(agentcore.EventSessionStart, start)
	return sl
}

// writeEnd records the terminal session.end event. It is idempotent: the
// first call wins. Callers should invoke this whenever a harnesses.FinalData
// is produced — finalizeAndEmit threads it together with the public-stream
// emit so the two views stay consistent.
func (sl *serviceSessionLog) writeEnd(req ServiceExecuteRequest, meta map[string]string, final harnesses.FinalData) {
	if sl == nil || sl.logger == nil {
		return
	}
	sl.endOnce.Do(func() {
		sl.endWrote.Store(true)
		end := session.SessionEndData{
			Status:           harnessStatusToCoreStatus(final.Status),
			Output:           final.FinalText,
			Tokens:           finalUsageToCoreTokens(final.Usage),
			DurationMs:       final.DurationMS,
			SelectedRoute:    req.SelectedRoute,
			SelectedEndpoint: sl.decision.Endpoint,
			Sticky: session.RoutingStickyState{
				KeyPresent:     req.CorrelationID != "",
				Assignment:     sl.decision.Sticky.Assignment,
				ServerInstance: sl.decision.Sticky.ServerInstance,
				Reason:         sl.decision.Sticky.Reason,
			},
			Utilization: session.RoutingUtilizationState{
				Source:         sl.decision.Utilization.Source,
				Freshness:      sl.decision.Utilization.Freshness,
				ActiveRequests: sl.decision.Utilization.ActiveRequests,
				QueuedRequests: sl.decision.Utilization.QueuedRequests,
				MaxConcurrency: sl.decision.Utilization.MaxConcurrency,
				CachePressure:  sl.decision.Utilization.CachePressure,
				ObservedAt:     sl.decision.Utilization.ObservedAt,
			},
			RequestedHarness:  req.Harness,
			ResolvedHarness:   "",
			HarnessSource:     harnessSource(req),
			RequestedModel:    req.Model,
			RequestedModelRef: req.ModelRef,
			ResolvedModelRef:  req.ResolvedModelRef,
			Reasoning:         req.Reasoning,
			Metadata:          meta,
			Error:             final.Error,
		}
		if final.CostUSD > 0 {
			cost := final.CostUSD
			end.CostUSD = &cost
		}
		if final.RoutingActual != nil {
			end.ResolvedHarness = final.RoutingActual.Harness
			end.Model = final.RoutingActual.Model
			end.SelectedProvider = final.RoutingActual.Provider
			if final.RoutingActual.ServerInstance != "" {
				end.SelectedServerInstance = final.RoutingActual.ServerInstance
			}
			end.ResolvedModel = final.RoutingActual.Model
			end.AttemptedProviders = append([]string(nil), final.RoutingActual.FallbackChainFired...)
			if len(end.AttemptedProviders) > 1 {
				end.FailoverCount = len(end.AttemptedProviders) - 1
			}
		}
		if end.SelectedServerInstance == "" {
			end.SelectedServerInstance = sl.decision.ServerInstance
		}
		sl.logger.Emit(agentcore.EventSessionEnd, end)
	})
}

// writeEvent persists a raw agent event to the session log. Used by the
// native loop callback to capture llm.request / llm.response / tool.call /
// compaction.* events so kept-sandbox bundles preserve a complete trace
// for benchmark reruns and post-mortem debugging. session.start and
// session.end are skipped because writeStart/writeEnd own those records and
// enrich them with service-side routing fields the loop does not see.
func (sl *serviceSessionLog) writeEvent(ev agentcore.Event) {
	if sl == nil || sl.logger == nil {
		return
	}
	switch ev.Type {
	case agentcore.EventSessionStart, agentcore.EventSessionEnd,
		agentcore.EventOverride, agentcore.EventRejectedOverride:
		return
	}
	sl.logger.Write(ev)
}

// writeOverrideEvent persists an override or rejected_override payload to
// the session log so windowed reporting (UsageReport, ADR-006 §5) can
// recompute routing-quality across restarts and beyond the in-memory
// ring's bounded retention. eventType is one of ServiceEventTypeOverride
// / ServiceEventTypeRejectedOverride.
func (sl *serviceSessionLog) writeOverrideEvent(eventType string, payload ServiceOverrideData) {
	if sl == nil || sl.logger == nil {
		return
	}
	payload.SessionID = sl.sessionID
	sl.logger.Emit(agentcore.EventType(eventType), payload)
}

// close flushes the underlying file. Safe to call multiple times.
func (sl *serviceSessionLog) close() {
	if sl == nil || sl.logger == nil {
		return
	}
	sl.closeOnce.Do(func() {
		_ = sl.logger.Close()
	})
}

// endWritten reports whether writeEnd has already recorded a terminal event.
func (sl *serviceSessionLog) endWritten() bool {
	if sl == nil {
		return false
	}
	return sl.endWrote.Load()
}

// persistRejectedOverride writes a session.start + rejected_override pair
// to a freshly-opened session log for sessionID. Used by Execute's
// pre-dispatch rejection branch, which never reaches runExecute and so
// never goes through the normal openSessionLog path. Without this,
// rejected_override events are invisible to UsageReport (which scans
// session logs over a --since window).
//
// The session.start is required by ScanRoutingQuality, which only counts
// log files that include one — and we want this rejection counted in
// TotalRequests so AutoAcceptanceRate reflects reality.
func (s *service) persistRejectedOverride(req ServiceExecuteRequest, sessionID string, payload ServiceOverrideData) {
	if req.SessionLogDir == "" || sessionID == "" {
		return
	}

package fizeau

import (
	"context"
	"fmt"
	"sync"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	"github.com/DocumentDrivenDX/fizeau/internal/serviceimpl"
)

// sessionHub is a concurrent-safe broadcast store for in-flight and completed
// sessions. It is held on the service struct and used by both Execute (to
// register/broadcast events) and TailSessionLog (to subscribe).
//
// Lifecycle:
//  1. Execute registers a session via openSession before the goroutine starts.
//  2. The runExecute goroutine calls broadcastEvent for every event it emits.
//  3. When runExecute is done (channel closes), it calls closeSession, which
//     marks the session complete and closes all subscriber channels.
//  4. TailSessionLog calls subscribe, which returns either an active subscriber
//     channel (for in-progress sessions) or a one-shot channel that immediately
//     yields the stored final event then closes (for completed sessions).
type sessionHub struct {
	mu       sync.Mutex
	sessions map[string]*hubSession
}

type hubSession struct {
	// done is true once the session has ended (all events emitted).
	done bool
	// finalEvent is the last event emitted (type=final). Stored for late
	// subscribers that attach after the session ends.
	finalEvent *ServiceEvent
	// subscribers receive a copy of every future broadcast. Each subscriber
	// has its own buffered channel; slow consumers are dropped (non-blocking
	// send with overflow discard).
	subscribers []chan ServiceEvent
}

func newSessionHub() *sessionHub {
	return &sessionHub{sessions: make(map[string]*hubSession)}
}

// openSession registers a new session. Must be called before Execute starts
// its goroutine so that TailSessionLog callers that arrive immediately after
// Execute returns can observe the session.
func (h *sessionHub) openSession(sessionID string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.sessions[sessionID] = &hubSession{}
}

// broadcastEvent sends ev to all active subscribers for sessionID. Slow
// subscribers (full channel) are skipped to avoid blocking Execute.
func (h *sessionHub) broadcastEvent(sessionID string, ev ServiceEvent) {
	h.mu.Lock()
	defer h.mu.Unlock()
	sess, ok := h.sessions[sessionID]
	if !ok || sess.done {
		return
	}
	for _, sub := range sess.subscribers {
		select {
		case sub <- ev:
		default:
			// Subscriber channel full — discard to avoid blocking Execute.
		}
	}
}

// closeSession marks the session done, stores the final event, and closes
// all subscriber channels. After this call no new events will be broadcast.
func (h *sessionHub) closeSession(sessionID string, finalEv ServiceEvent) {
	h.mu.Lock()
	defer h.mu.Unlock()
	sess, ok := h.sessions[sessionID]
	if !ok {
		return
	}
	sess.done = true
	sess.finalEvent = &finalEv
	for _, sub := range sess.subscribers {
		close(sub)
	}
	sess.subscribers = nil
}

// subscribe returns a channel that will receive all subsequent events for
// sessionID and then be closed when the session ends. If the session is
// already complete, the channel receives the stored final event then closes
// immediately. Returns an error for unknown session IDs.
func (h *sessionHub) subscribe(sessionID string) (<-chan ServiceEvent, error) {
	h.mu.Lock()
	defer h.mu.Unlock()

	sess, ok := h.sessions[sessionID]
	if !ok {
		return nil, fmt.Errorf("unknown session %q", sessionID)
	}

	ch := make(chan ServiceEvent, 32)

	if sess.done {
		// Session already completed: deliver final event then close.
		go func() {
			if sess.finalEvent != nil {
				ch <- *sess.finalEvent
			}
			close(ch)
		}()
		return ch, nil
	}

	// Session in progress: register as a subscriber.
	sess.subscribers = append(sess.subscribers, ch)
	return ch, nil
}

// TailSessionLog streams events from an in-progress or completed session by
// ID. Multiple concurrent callers on the same sessionID each receive the full
// remaining event stream. Callers attached after completion receive the stored
// final event then see the channel close. Returns an error for unknown IDs.
func (s *service) TailSessionLog(ctx context.Context, sessionID string) (<-chan ServiceEvent, error) {
	return serviceimpl.TailSessionLog(ctx, sessionID, s.hub.subscribe)
}

// wrapExecuteWithHub wraps the inner out channel so that every event emitted
// by runExecute is also broadcast to TailSessionLog subscribers. Returns a
// write-only channel that Execute's goroutine writes to; reads are done by
// the fan-out goroutine which forwards to both the caller's (outer) channel
// and the hub.
//
// Usage in Execute:
//
//	outer := make(chan ServiceEvent, 64)   // returned to caller
//	inner, cleanup := s.hub.wrapExecuteWithHub(sessionID, outer)
//	go s.runExecute(ctx, req, decision, meta, inner)
//	return outer, nil
//
// The fan-out goroutine closes outer when inner closes, and calls
// closeSession on the hub with the last final event seen.
func (h *sessionHub) wrapExecuteWithHub(sessionID string, outer chan ServiceEvent, ovr *overrideContext, meta map[string]string) (inner chan ServiceEvent) {
	inner = make(chan ServiceEvent, 64)
	go func() {
		defer close(outer)
		var lastFinal ServiceEvent
		for ev := range inner {
			// ADR-006 §7: emit the override event immediately before the
			// final event so consumers correlating per-session can join
			// cleanly. Outcome is populated from the final event itself.
			if ev.Type == harnesses.EventTypeFinal && ovr != nil && !ovr.emitted.Load() {
				if overrideEv, payload, ok := makeOverrideEvent(ovr, sessionID, ev, meta); ok {
					ovr.emitted.Store(true)
					// Back-write the outcome onto the in-memory ring so
					// RouteStatus aggregates surface real success/stalled/
					// failed counts (ADR-006 §5).
					stampOutcomeOnRecord(ovr.record, payload.Outcome)
					select {
					case outer <- overrideEv:
					case <-time.After(5 * time.Second):
					}
					h.broadcastEvent(sessionID, overrideEv)
				}
			}
			// Forward to the caller's channel.
			select {
			case outer <- ev:
			case <-time.After(5 * time.Second):
				// Caller stopped reading — discard but keep broadcasting.
			}
			// Broadcast to hub subscribers.
			h.broadcastEvent(sessionID, ev)
			// Track the final event for post-completion subscribers.
			if ev.Type == harnesses.EventTypeFinal {
				lastFinal = ev
			}
		}
		h.closeSession(sessionID, lastFinal)
	}()
	return inner
}

package fizeau

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"sync/atomic"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/compaction"
	agentcore "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	"github.com/DocumentDrivenDX/fizeau/internal/modelcatalog"
	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
	"github.com/DocumentDrivenDX/fizeau/internal/routing"
	"github.com/DocumentDrivenDX/fizeau/internal/serviceimpl"
	"github.com/DocumentDrivenDX/fizeau/internal/tool"
)

// generateSessionID returns a unique session identifier for a new Execute.
func generateSessionID() string {
	return fmt.Sprintf("svc-%d", time.Now().UnixNano())
}

// Execute runs an agent task in-process; emits Events on the returned
// channel until the task terminates (channel closes). The final event
// (type=final) carries status, usage, cost, session-log path, and the
// resolved fallback chain that fired.
//
// See CONTRACT-003 §"Behaviors the contract guarantees" for the full
// behavior contract this method honors:
//   - Orphan-model validation (Status=failed when Model unknown)
//   - Provider-deadline wrapping (Timeout + IdleTimeout + ProviderTimeout)
//   - StallPolicy enforcement (stall event before final)
//   - Route-reason attribution (routing_decision start, routing_actual final)
//   - OS-level subprocess cleanup on ctx.Done()
//   - Metadata bidirectional echo (events + session log)
//   - SessionLogDir per-request override
//
// Routing: under-specified requests (no Harness) are dispatched through
// internal/routing.Resolve via ResolveRoute. Callers can run with bare
// Profile/ModelRef/Model/Provider — the engine picks. NativeProvider must
// still be supplied for the native path until provider construction lands
// in a follow-up.
func (s *service) Execute(ctx context.Context, req ServiceExecuteRequest) (<-chan ServiceEvent, error) {
	// Boundary validation: reject unknown CachePolicy values before any
	// session state is opened or events are emitted. Beads C/D consume this
	// field; an unknown value is a caller programming error.
	if err := ValidateCachePolicy(req.CachePolicy); err != nil {
		return nil, err
	}
	if err := ValidatePowerBounds(req.MinPower, req.MaxPower); err != nil {
		return nil, err
	}
	if err := ValidateRole(req.Role); err != nil {
		return nil, err
	}
	if err := ValidateCorrelationID(req.CorrelationID); err != nil {
		return nil, err
	}

	// Generate a session ID and register it in the hub so TailSessionLog
	// callers can subscribe before or during execution.
	sessionID := generateSessionID()
	fanout := s.executeEventFanout()
	fanout.openSession(sessionID)

	outer := make(chan ServiceEvent, 64)

	// ADR-006 §3/§4: capture the override context (user pin + unconstrained
	// auto decision) before route resolution so we can fire the matching
	// override / rejected_override event regardless of which path the route
	// resolution takes.
	overrideCtx := s.buildOverrideContext(ctx, req)

	// ADR-006 §5: record this request into the routing-quality store so
	// auto_acceptance_rate / override_disagreement_rate / class_breakdown
	// reflect both overridden and non-overridden traffic. The recorded
	// override payload carries no outcome — outcome aggregation for live
	// requests is best-effort and lives in session logs once that
	// persistence path lands.
	s.recordRoutingQualityForRequest(overrideCtx)

	// Resolve the route.
	decision, err := s.executeRouteResolver().resolveExecuteRoute(req)
	if err != nil {
		// NoViableProviderForNow is a transient quota signal — DDx
		// callers pause their drain loop on RetryAfter and resume.
		// Surface it directly (not via the fatal-final channel) so the
		// typed error reaches errors.As without log scraping.
		var quotaErr *NoViableProviderForNow
		if errors.As(err, &quotaErr) {
			fanout.closeSession(sessionID, ServiceEvent{})
			return nil, err
		}
		if isExplicitPinError(err) {
			// Emit a rejected_override event (no outcome) when the pin
			// fails pre-dispatch. Surface the typed error wrapped with
			// the rejected_override payload so callers that errors.As
			// the typed pin error still get it; callers wanting the
			// telemetry can extract via AsRejectedOverride.
			pinErr := err
			if overrideCtx != nil {
				if rejectedEv, payload, ok := makeRejectedOverrideEvent(overrideCtx, sessionID, pinErr, req.Metadata); ok {
					fanout.broadcastEvent(sessionID, rejectedEv)
					// Persist the rejected_override to the session log so
					// UsageReport's windowed scan (which sources from
					// session logs, not the in-memory ring) sees this
					// rejection. The pin failed pre-dispatch, so no
					// runExecute will open a log for this session — open
					// one briefly here, write session.start + the rejected
					// payload, and close.
					s.persistRejectedOverride(req, sessionID, payload)
					pinErr = &ErrRejectedOverride{Inner: err, Event: payload}
				}
			}
			fanout.closeSession(sessionID, ServiceEvent{})
			return nil, pinErr
		}
		// Still return a channel that yields a single failed final event so
		// downstream consumers don't have to special-case the error path.
		// Also close the hub session so TailSessionLog subscribers unblock.
		go func() {
			emitFatalFinal(outer, req.Metadata, "failed", err.Error())
			// Drain outer to get the final event and forward to hub.
			// emitFatalFinal closes outer; read the single event from it.
		}()
		// We can't easily intercept emitFatalFinal here, so close the hub
		// session with an empty final immediately — callers on TailSessionLog
		// for a failed-route session get an empty close.
		go func() {
			// Wait briefly for emitFatalFinal to write.
			time.Sleep(10 * time.Millisecond)
			fanout.closeSession(sessionID, ServiceEvent{})
		}()
		return outer, nil
	}

	// Metadata seam: every event we emit echoes req.Metadata.
	meta := req.Metadata

	// Wrap the inner channel through the hub so every event is broadcast to
	// TailSessionLog subscribers. The fan-out goroutine owns outer's close
	// and is responsible for inserting the override event (if any) immediately
	// before the final event per ADR-006 §7.
	inner := fanout.wrapExecuteWithHub(sessionID, outer, overrideCtx, meta)

	// Emit start-of-execution routing_decision so consumers know the picked
	// chain before any real work fires. The actual chain (post-fallback) is
	// stamped onto the final event's RoutingActual field.
	go s.runExecute(ctx, req, *decision, meta, inner, sessionID, overrideCtx)
	return outer, nil
}

// resolveExecuteRoute reduces the request to a concrete RouteDecision.
// The request is dispatched through the routing engine
// (internal/routing.Resolve) when under-specified, or accepted verbatim
// when Harness is set explicitly.
func (s *service) resolveExecuteRoute(req ServiceExecuteRequest) (*RouteDecision, error) {
	// If Harness is omitted, route through the engine. The engine defaults to
	// local-first and auto-selects from configured endpoints when no other
	// constraints are specified — an empty request is valid if providers exist.
	if req.Harness == "" {
		return s.resolveExecuteRouteWithEngine(req)
	}
	canonical := harnesses.ResolveHarnessAlias(req.Harness)
	if !s.registry.Has(canonical) {
		return nil, fmt.Errorf("unknown harness %q", req.Harness)
	}
	cfg, _ := s.registry.Get(canonical)
	if err := validateExplicitHarnessProfile(canonical, cfg, req.Profile); err != nil {
		return nil, err
	}
	if err := validateExplicitProvider(s.opts.ServiceConfig, cfg, req.Provider); err != nil {
		return nil, err
	}
	if err := validateExplicitHarnessModel(canonical, cfg, req.Model, req.Provider); err != nil {
		return nil, err
	}
	if err := validateExplicitHarnessReasoning(canonical, cfg, req.Reasoning); err != nil {
		return nil, err
	}
	if err := validateExplicitHarnessQuota(canonical, cfg); err != nil {
		return nil, err
	}
	resolvedModel := resolveSubprocessModelAlias(canonical, req.Model)
	decision := &RouteDecision{
		Harness:  canonical,
		Provider: req.Provider,
		Model:    resolvedModel,
		Reason:   "explicit",
		Power:    catalogPowerForModel(serviceRoutingCatalog(), resolvedModel),
	}
	if decision.Endpoint == "" {
		_, endpoint, _ := splitEndpointProviderRef(decision.Provider)
		decision.Endpoint = endpoint
	}
	return decision, nil
}

func validateExplicitHarnessQuota(name string, cfg harnesses.HarnessConfig) error {
	if !cfg.IsSubscription {
		return nil
	}
	now := time.Now()
	qs, ok := subscriptionQuotaForHarness(name, now)
	if !ok || !qs.Present || !qs.Fresh || qs.OK {
		return nil
	}
	return explicitQuotaUnavailable(name, qs.Windows, now)
}

func explicitQuotaUnavailable(name string, windows []harnesses.QuotaWindow, now time.Time) error {
	retryAfter := earliestQuotaResetAfter(windows, now)
	if retryAfter.IsZero() {
		retryAfter = now.Add(defaultQuotaRecoveryFallbackInterval)
	}
	return &NoViableProviderForNow{
		RetryAfter:         retryAfter,
		ExhaustedProviders: []string{name},
	}
}

func earliestQuotaResetAfter(windows []harnesses.QuotaWindow, now time.Time) time.Time {
	var earliest time.Time
	for _, window := range windows {
		if window.ResetsAtUnix <= 0 {
			continue
		}
		reset := time.Unix(window.ResetsAtUnix, 0)
		if !reset.After(now) {
			continue
		}
		if earliest.IsZero() || reset.Before(earliest) {
			earliest = reset
		}
	}
	return earliest
}

func validateExplicitHarnessProfile(name string, cfg harnesses.HarnessConfig, profile string) error {
	constraint, ok := explicitProfileConstraint(profile)
	if !ok {
		return nil
	}
	switch constraint {
	case routing.ProviderPreferenceLocalOnly:
		if !cfg.IsLocal {
			return &ErrProfilePinConflict{
				Profile:           profile,
				ConflictingPin:    "Harness=" + name,
				ProfileConstraint: constraint,
			}
		}
	case routing.ProviderPreferenceSubscriptionOnly:
		if !cfg.IsSubscription {
			return &ErrProfilePinConflict{
				Profile:           profile,
				ConflictingPin:    "Harness=" + name,
				ProfileConstraint: constraint,
			}
		}
	}
	return nil
}

func explicitProfileConstraint(profile string) (string, bool) {
	switch profile {
	case "local", "offline", "air-gapped":
		return routing.ProviderPreferenceLocalOnly, true
	case "smart", "code-smart", "code-high":
		return routing.ProviderPreferenceSubscriptionOnly, true
	default:
		return "", false
	}
}

func isExplicitPinError(err error) bool {
	var modelConstraintAmbiguous *ErrModelConstraintAmbiguous
	if errors.As(err, &modelConstraintAmbiguous) {
		return true
	}
	var modelConstraintNoMatch *ErrModelConstraintNoMatch
	if errors.As(err, &modelConstraintNoMatch) {
		return true
	}
	var modelErr *ErrHarnessModelIncompatible
	if errors.As(err, &modelErr) {
		return true
	}
	var profileErr *ErrProfilePinConflict
	if errors.As(err, &profileErr) {
		return true
	}
	var providerErr *ErrUnknownProvider
	return errors.As(err, &providerErr)
}

// validateExplicitProvider rejects pre-dispatch when the caller pinned a
// provider name that the service configuration does not recognize. Returns
// nil when no provider was pinned, when no ServiceConfig is configured (no
// provider catalog to validate against), when the provider name is known,
// or when the harness is test-only / does not consume Provider (virtual,
// script, etc. have no real provider lookup).
func validateExplicitProvider(sc ServiceConfig, cfg harnesses.HarnessConfig, provider string) error {
	if provider == "" || sc == nil {
		return nil
	}
	if cfg.TestOnly {
		return nil
	}
	lookup := provider
	if base, _, ok := splitEndpointProviderRef(provider); ok {
		lookup = base
	}
	if _, ok := sc.Provider(lookup); ok {
		return nil
	}
	known := sc.ProviderNames()
	return &ErrUnknownProvider{Provider: provider, KnownProviders: append([]string(nil), known...)}
}

func validateExplicitHarnessModel(name string, cfg harnesses.HarnessConfig, model, provider string) error {
	if model == "" || cfg.TestOnly || cfg.IsHTTPProvider || name == "fiz" {
		return nil
	}
	if modelSupportedForHarness(name, cfg, model, provider) {
		return nil
	}
	supportedModels := subprocessHarnessModelIDs(name, cfg)
	return &ErrHarnessModelIncompatible{
		Harness:         name,
		Model:           model,
		SupportedModels: append([]string(nil), supportedModels...),
	}
}

func modelSupportedForHarness(name string, cfg harnesses.HarnessConfig, model, provider string) bool {
	for _, known := range subprocessHarnessModelIDs(name, cfg) {
		if model == known {
			return true
		}
	}
	switch name {
	case "codex":
		return strings.HasPrefix(model, "gpt-")
	case "claude":
		return strings.HasPrefix(model, "claude-")
	case "pi":
		// Pi can route to non-Gemini backends (lmstudio, omlx, etc.) when a
		// provider is pinned. The pi CLI owns per-provider model validation
		// in that case, so the agent-side gate trusts the provider pin and
		// defers concrete model-ID checks to pi --list-models / pi itself.
		return provider != ""
	default:
		return len(cfg.Models) == 0
	}
}

func validateExplicitHarnessReasoning(name string, cfg harnesses.HarnessConfig, value Reasoning) error {
	if cfg.TestOnly {
		return nil
	}
	if len(cfg.ReasoningLevels) == 0 && cfg.MaxReasoningTokens <= 0 {
		return nil
	}
	policy, err := reasoning.ParseString(string(value))
	if err != nil {
		return fmt.Errorf("unsupported reasoning %q for harness %q: %w", value, name, err)
	}
	switch policy.Kind {
	case reasoning.KindUnset, reasoning.KindAuto, reasoning.KindOff:
		return nil
	case reasoning.KindTokens:
		if cfg.MaxReasoningTokens <= 0 {
			return fmt.Errorf("unsupported reasoning %q for harness %q; token budgets are not supported", value, name)
		}
		if policy.Tokens > cfg.MaxReasoningTokens {
			return fmt.Errorf("unsupported reasoning %q for harness %q; max token budget is %d", value, name, cfg.MaxReasoningTokens)
		}
		return nil
	case reasoning.KindNamed:
		for _, supported := range cfg.ReasoningLevels {
			if string(policy.Value) == supported {
				return nil
			}
		}
		return fmt.Errorf("unsupported reasoning %q for harness %q; supported reasoning: %s", value, name, strings.Join(cfg.ReasoningLevels, ", "))
	default:
		return fmt.Errorf("unsupported reasoning %q for harness %q", value, name)
	}
}

func harnessSource(req ServiceExecuteRequest) string {
	if strings.TrimSpace(req.Harness) != "" {
		return "request_harness"
	}
	return "auto_route"
}

// runExecute is the per-Execute goroutine. It owns the channel close path
// and the final event emit. All termination paths funnel through emitFinal
// so the channel always sees a final event before close.
func (s *service) runExecute(ctx context.Context, req ServiceExecuteRequest, decision RouteDecision, meta map[string]string, out chan<- ServiceEvent, sessionID string, overrideCtx *overrideContext) {
	defer close(out)

	start := time.Now()
	var seq atomic.Int64

	// Open the service-owned session log writer and guarantee a terminal
	// session.end record plus a clean file close even on unexpected exits.
	// CONTRACT-003 makes session-log lifecycle a service responsibility; the
	// per-path finalizeAndEmit calls below feed writeEnd in lock-step with
	// the public final event.
	sl := s.executeSessionLogOpener().openSessionLog(req, decision, sessionID)
	if overrideCtx != nil {
		sl.override = overrideCtx
	}
	defer func() {
		if !sl.endWritten() {
			sl.writeEnd(req, meta, harnesses.FinalData{
				Status:     "cancelled",
				Error:      "session ended without final event",
				DurationMS: time.Since(start).Milliseconds(),
				RoutingActual: &harnesses.RoutingActual{
					Harness:  decision.Harness,
					Provider: decision.Provider,
					Model:    decision.Model,
				},
			})
		}
		sl.close()
	}()

	// Wall-clock cap.
	runCtx := ctx
	if req.Timeout > 0 {
		var cancel context.CancelFunc
		runCtx, cancel = context.WithTimeout(ctx, req.Timeout)
		defer cancel()
	}

	// Emit routing_decision start event. Include session_id so callers can
	// extract it and pass to TailSessionLog. Per CONTRACT-003 the
	// top-level Role + CorrelationID are echoed into routing_decision
	// event Metadata (top-level wins over caller Metadata for these
	// reserved keys).
	routingMeta := metaWithRoleAndCorrelation(meta, req.Role, req.CorrelationID)
	emitJSON(out, &seq, harnesses.EventTypeRoutingDecision, routingMeta, ServiceRoutingDecisionData{
		Harness:        decision.Harness,
		Provider:       decision.Provider,
		Endpoint:       decision.Endpoint,
		ServerInstance: decision.ServerInstance,
		Model:          decision.Model,
		Reason:         decision.Reason,
		Sticky: ServiceRoutingStickyState{
			KeyPresent:     decision.Sticky.KeyPresent,
			Assignment:     decision.Sticky.Assignment,
			ServerInstance: decision.Sticky.ServerInstance,
			Reason:         decision.Sticky.Reason,
		},
		Utilization: ServiceRoutingUtilizationState{
			Source:         decision.Utilization.Source,
			Freshness:      decision.Utilization.Freshness,
			ActiveRequests: decision.Utilization.ActiveRequests,
			QueuedRequests: decision.Utilization.QueuedRequests,
			MaxConcurrency: decision.Utilization.MaxConcurrency,
			CachePressure:  decision.Utilization.CachePressure,
			ObservedAt:     decision.Utilization.ObservedAt,
		},
		RequestedHarness: req.Harness,
		HarnessSource:    harnessSource(req),
		SessionID:        sessionID,
		Candidates:       routingDecisionEventCandidates(decision.Candidates),
	})
	emitProgress(out, &seq, sl, sessionID, meta, routeProgressData(decision))

	s.executeRunnerInvoker().dispatchExecuteRun(runCtx, executeRunContext{
		req:      req,
		decision: decision,
		meta:     meta,
		out:      out,
		seq:      &seq,
		start:    start,
		sl:       sl,
		session:  sessionID,
	})
}

func (s *service) runVirtual(ctx context.Context, req ServiceExecuteRequest, decision RouteDecision, meta map[string]string, out chan<- ServiceEvent, seq *atomic.Int64, start time.Time, sl *serviceSessionLog, sessionID string) {
	progress := newSubprocessProgressState(req)
	emitProgress(out, seq, sl, sessionID, meta, progress.noteRequestStart())
	result := serviceimpl.RunVirtual(ctx, executeRunnerRequest(req, decision, meta, start))
	final := result.Final
	if result.EmitText {
		emitJSONRaw(out, seq, harnesses.EventTypeTextDelta, meta, harnesses.TextDeltaData{Text: result.Text})
	}
	if progressFinal := progress.noteResponseComplete(final); progressFinal != nil {
		emitProgress(out, seq, sl, sessionID, meta, *progressFinal)
	}
	finalizeAndEmit(out, seq, meta, req, sl, final)
}

func (s *service) runScript(ctx context.Context, req ServiceExecuteRequest, decision RouteDecision, meta map[string]string, out chan<- ServiceEvent, seq *atomic.Int64, start time.Time, sl *serviceSessionLog, sessionID string) {
	progress := newSubprocessProgressState(req)
	emitProgress(out, seq, sl, sessionID, meta, progress.noteRequestStart())
	result := serviceimpl.RunScript(ctx, executeRunnerRequest(req, decision, meta, start))
	final := result.Final
	if result.EmitText {
		emitJSONRaw(out, seq, harnesses.EventTypeTextDelta, meta, harnesses.TextDeltaData{Text: result.Text})
	}
	if progressFinal := progress.noteResponseComplete(final); progressFinal != nil {
		emitProgress(out, seq, sl, sessionID, meta, *progressFinal)
	}
	finalizeAndEmit(out, seq, meta, req, sl, final)
}

func executeRunnerRequest(req ServiceExecuteRequest, decision RouteDecision, meta map[string]string, start time.Time) serviceimpl.ExecuteRunnerRequest {

package session

import (
	"encoding/json"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"sync"

	agent "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/safefs"
)

// Logger writes session events to a JSONL file.
type Logger struct {
	dir       string
	sessionID string
	mu        sync.Mutex
	file      *os.File
	seq       int
	warned    bool
}

// NewLogger creates a Logger that writes to the given directory.
// If the directory does not exist, it is created. If creation fails,
// the logger will silently skip writes (best-effort logging).
func NewLogger(dir, sessionID string) *Logger {
	l := &Logger{
		dir:       dir,
		sessionID: sessionID,
	}
	if err := safefs.MkdirAll(dir, 0o750); err != nil {
		slog.Warn("session logger: cannot create directory", "dir", dir, "err", err)
		l.warned = true
		return l
	}
	path := filepath.Join(dir, sessionID+".jsonl")
	f, err := safefs.Create(path)
	if err != nil {
		slog.Warn("session logger: cannot create file", "path", path, "err", err)
		l.warned = true
		return l
	}
	l.file = f
	return l
}

// Callback returns an EventCallback suitable for agent.Request.Callback.
func (l *Logger) Callback() agent.EventCallback {
	return func(e agent.Event) {
		l.Write(e)
	}
}

// Emit creates and writes an event with auto-incrementing sequence number.
func (l *Logger) Emit(eventType agent.EventType, data any) {
	l.mu.Lock()
	seq := l.seq
	l.seq++
	l.mu.Unlock()

	event := NewEvent(l.sessionID, seq, eventType, data)
	l.Write(event)
}

// Write appends a pre-built event to the log file.
func (l *Logger) Write(e agent.Event) {
	l.mu.Lock()
	defer l.mu.Unlock()

	if l.file == nil {
		return
	}

	line, err := json.Marshal(e)
	if err != nil {
		if !l.warned {
			slog.Warn("session logger: marshal error", "err", err)
			l.warned = true
		}
		return
	}
	line = append(line, '\n')
	if _, err := l.file.Write(line); err != nil {
		if !l.warned {
			slog.Warn("session logger: write error", "err", err)
			l.warned = true
		}
	}
}

// Close flushes and closes the log file.
func (l *Logger) Close() error {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.file == nil {
		return nil
	}
	file := l.file
	l.file = nil
	return file.Close()
}

// ReadEvents reads all events from a session log file.
func ReadEvents(path string) ([]agent.Event, error) {
	data, err := safefs.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("session: reading log: %w", err)
	}

	var events []agent.Event
	dec := json.NewDecoder(jsonlReader(data))
	for dec.More() {
		var e agent.Event
		if err := dec.Decode(&e); err != nil {
			return events, fmt.Errorf("session: decoding event: %w", err)
		}
		events = append(events, e)
	}
	return events, nil
}

